CREATE TABLE IF NOT EXISTS schema_versions(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_versions(version) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS members(user_id uuid REFERENCES users(id), workspace_id uuid REFERENCES workspaces(id), role text NOT NULL CHECK(role IN ('owner','member')), PRIMARY KEY(user_id,workspace_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf_hash text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key text NOT NULL, happened_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS login_attempts_key ON login_attempts(key,happened_at);
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), title text NOT NULL, content text NOT NULL, source text NOT NULL, version integer NOT NULL, content_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS documents_workspace ON documents(workspace_id,active);
CREATE INDEX IF NOT EXISTS documents_search ON documents USING gin(to_tsvector('english', title || ' ' || content));
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), owner_id uuid NOT NULL REFERENCES users(id), idempotency_key text NOT NULL, input_hash text NOT NULL, request jsonb NOT NULL, status text NOT NULL CHECK(status IN ('queued','running','approval','completed','blocked','failed','cancelled','rejected')), stage text NOT NULL DEFAULT 'queued', attempt integer NOT NULL DEFAULT 0, lease_token uuid, lease_until timestamptz, result jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key));
CREATE INDEX IF NOT EXISTS tasks_queue ON tasks(status,created_at);
CREATE TABLE IF NOT EXISTS events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id), kind text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals(task_id uuid PRIMARY KEY REFERENCES tasks(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), payload jsonb NOT NULL, payload_hash text NOT NULL, expires_at timestamptz NOT NULL, decision text CHECK(decision IN ('approved','rejected')), actor_id uuid REFERENCES users(id), decided_at timestamptz);
CREATE TABLE IF NOT EXISTS receipts(id uuid PRIMARY KEY, task_id uuid UNIQUE NOT NULL REFERENCES tasks(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), operation text NOT NULL, payload_hash text NOT NULL, verification text NOT NULL, artifact jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commitments(id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), description text NOT NULL, source_ids jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS episodes(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), task_id uuid UNIQUE NOT NULL REFERENCES tasks(id), summary text NOT NULL, source_ids jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS worker_heartbeats(service text PRIMARY KEY, updated_at timestamptz NOT NULL);
